CREATE TABLE device_links(id TEXT PRIMARY KEY,secret_hash TEXT NOT NULL,code TEXT NOT NULL UNIQUE,device_name TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,user_id TEXT REFERENCES users(id),user_version INTEGER,approved_session TEXT,consumed_at TEXT);
CREATE TABLE render_devices(id TEXT PRIMARY KEY,udn TEXT NOT NULL UNIQUE,name TEXT NOT NULL,address TEXT NOT NULL,transport_url TEXT NOT NULL,transport_type TEXT NOT NULL,render_url TEXT,render_type TEXT,protocols TEXT NOT NULL DEFAULT '',last_seen TEXT NOT NULL);
CREATE TABLE receiver_grants(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,user_id TEXT NOT NULL REFERENCES users(id),login_id TEXT NOT NULL,playback_id TEXT NOT NULL REFERENCES playback_leases(id) ON DELETE CASCADE,target_id TEXT REFERENCES render_devices(id),target_name TEXT NOT NULL,mode TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,closed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE receiver_copies(media_id TEXT PRIMARY KEY REFERENCES media(id) ON DELETE CASCADE,fingerprint TEXT NOT NULL,match_revision INTEGER NOT NULL,path TEXT NOT NULL,size_bytes INTEGER NOT NULL,created_at TEXT NOT NULL);
